<form method="get" class="dashboard-range"><label for="dashboard-days">Reporting period</label><select id="dashboard-days" name="days"><?php foreach($periods as $n=>$label): ?><option value="<?= $n ?>" <?= $analytics['days']===$n?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="btn btn-secondary btn-sm" type="submit">Update</button><span class="muted small"><?= e($analytics['since']) ?> – <?= e($analytics['until']) ?></span></form>
<?php if(!$catalogReport): ?>
<div class="metric-grid four dashboard-metrics"><div class="metric-card"><span>Orders placed</span><strong><?= (int)$analytics['orders'] ?></strong><small>In selected period</small></div><div class="metric-card"><span>To prepare</span><strong><?= (int)$analytics['ready_to_prepare'] ?></strong><small>COD or provider-verified card orders</small></div><div class="metric-card"><span>Delivered</span><strong><?= (int)$analytics['statuses']['delivered'] ?></strong><small>Recorded fulfillment status</small></div><div class="metric-card"><span>Verified card order value</span><strong>₱<?= e(number_format((float)$analytics['verified_card_value'],2)) ?></strong><small>Provider-confirmed Sandbox value; not cash settlement</small></div></div>
<div class="analytics-grid"><section class="panel analytics-chart"><h2>Orders over time</h2><p class="muted small">Orders placed per day, including cancellations.</p>
 <?php $series=$analytics['series'];$peak=max(1,...array_values($series));$points=[];$i=0;foreach($series as $count){$points[]=round(12+($i++*676/max(1,count($series)-1)),2).','.round(168-($count/$peak*144),2);} ?>
 <svg class="orders-chart" viewBox="0 0 700 190" role="img" aria-label="Daily order counts. Exact values are in the table below."><path d="M12 24V168H688" fill="none" stroke="#b9ad9e"/><polyline points="<?= e(implode(' ',$points)) ?>" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><text x="12" y="187"><?= e(date('j M',strtotime(array_key_first($series)))) ?></text><text x="688" y="187" text-anchor="end"><?= e(date('j M',strtotime(array_key_last($series)))) ?></text><text x="12" y="17"><?= $peak ?> orders</text></svg>
 <details class="analytics-data"><summary>View daily counts</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th>Orders placed</th></tr></thead><tbody><?php foreach($series as $day=>$count): ?><tr><td><?= e($day) ?></td><td><?= $count ?></td></tr><?php endforeach; ?></tbody></table></div></details>
 </section><section class="panel"><h2>Fulfillment status</h2><div class="analytics-bars"><?php foreach($analytics['statuses'] as $status=>$count): ?><div><span><?= e(ucfirst($status)) ?></span><strong><?= (int)$count ?></strong><meter min="0" max="<?= max(1,$analytics['orders']) ?>" value="<?= (int)$count ?>"><?= (int)$count ?></meter></div><?php endforeach; ?></div><a class="text-link" href="<?= e(url('/admin/orders')) ?>">Manage orders →</a></section></div>
<?php endif; ?>
<div class="analytics-grid"><section class="panel"><div class="panel-head"><h2>Stock attention</h2><a href="<?= e(url('/catalog/inventory')) ?>">Inventory →</a></div><?php if(!$analytics['attention']): ?><p class="muted">No active products are low or out of stock.</p><?php else: ?><ul class="analytics-list"><?php foreach($analytics['attention'] as $p): ?><li><a href="<?= e(url('/catalog/products?edit='.(int)$p['id'])) ?>"><?= e($p['name']) ?><small><?= e($p['sku']) ?></small></a><strong class="<?= (int)$p['stock_qty']===0?'stock-zero':'' ?>"><?= (int)$p['stock_qty'] ?> left</strong></li><?php endforeach; ?></ul><?php endif; ?></section>
<section class="panel"><h2>Most ordered · fulfilled</h2><p class="muted small">Units in delivered orders placed in this period. Cancelled, unpaid card and simulated payments are excluded.</p><?php if(!$analytics['top']): ?><p class="analytics-empty">No qualifying fulfilled orders in this period.</p><?php else: ?><ol class="analytics-list"><?php foreach($analytics['top'] as $p): ?><li><span><?= e($p['name']) ?></span><strong><?= (int)$p['units'] ?> units</strong></li><?php endforeach; ?></ol><?php endif; ?></section></div>
<?php if($catalogReport): ?><section class="panel"><h2>Catalog by category</h2><div class="analytics-bars"><?php foreach($analytics['categories'] as $category): ?><div><span><?= e($category['name']) ?></span><strong><?= (int)$category['products'] ?></strong><meter min="0" max="<?= max(1,(int)$analytics['stock']['total']) ?>" value="<?= (int)$category['products'] ?>"><?= (int)$category['products'] ?></meter></div><?php endforeach; ?></div></section><?php endif; ?>
